<section class="garden-panel"><div class="garden-panel-heading"><div><span class="garden-kicker">MORE</span><h2>Find your tools</h2></div></div><p class="garden-muted">Additional tools available to your role. Everyday work stays in the main workspace menu.</p><label for="garden-tools-search">Find a tool<input type="search" id="garden-tools-search" placeholder="Search accounts, staff, setup…" autocomplete="off"></label></section>
<div class="garden-business-tools">
<?php foreach($business_tool_groups as $name=>$tools): ?><section class="garden-panel" data-tool-group><h2><?= htmlspecialchars($name); ?></h2><div class="garden-business-tool-grid"><?php foreach($tools as $tool): ?><a data-business-tool href="<?= htmlspecialchars($tool['url'],ENT_QUOTES,'UTF-8'); ?>"><span><?= htmlspecialchars($tool['label']); ?></span><i class="fa fa-arrow-right" aria-hidden="true"></i></a><?php endforeach; ?></div></section><?php endforeach; ?>
<p class="garden-card garden-muted" id="garden-tools-empty" <?= $business_tool_groups?'hidden':''; ?> role="status">No matching tools are available.</p>
</div>
<script>
(function(){function match(text,query){if(typeof window.mpSearchMatch==='function')return window.mpSearchMatch(text,query);var stop={search:1,find:1,look:1,lookup:1,show:1,filter:1,for:1,me:1,the:1,a:1,an:1,of:1,to:1,in:1,on:1,please:1,list:1,all:1},raw=String(query==null?'':query).toLowerCase().replace(/[^a-z0-9\s]+/g,' ').trim();if(!raw)return true;var tokens=[];raw.split(/\s+/).forEach(function(word){if(word.length<2||stop[word])return;if(word.length>3&&word.slice(-1)==='s')word=word.slice(0,-1);if(tokens.indexOf(word)===-1)tokens.push(word);});if(!tokens.length)return true;var hay=String(text==null?'':text).toLowerCase();return tokens.every(function(token){return hay.indexOf(token)!==-1;});}
var input=document.getElementById('garden-tools-search');input.addEventListener('input',function(){var count=0;document.querySelectorAll('[data-tool-group]').forEach(function(group){var visible=0;group.querySelectorAll('[data-business-tool]').forEach(function(link){var show=match(group.querySelector('h2').textContent+' '+link.textContent,input.value);link.hidden=!show;if(show){visible++;count++;}});group.hidden=!visible;});document.getElementById('garden-tools-empty').hidden=count>0;});})();
</script>
